
const projects=[{"id":"1","slug":"lacteo","number":"01","title":"Lácteo","thumbnail":"./assets/lacteo/lacteo-04.webp","gallery":["./assets/lacteo/lacteo-01.webp","./assets/lacteo/lacteo-02.webp","./assets/lacteo/lacteo-03.webp","./assets/lacteo/lacteo-04.webp","./assets/lacteo/lacteo-05.webp","./assets/lacteo/lacteo-06.webp","./assets/lacteo/lacteo-07.webp","./assets/lacteo/lacteo-08.webp","./assets/lacteo/lacteo-09.webp","./assets/lacteo/lacteo-10.webp","./assets/lacteo/lacteo-11.webp","./assets/lacteo/lacteo-12.webp"],"duration":"Independent Brand Project","role":"Creative Direction · Brand Identity · Packaging · Campaign · Digital","scope":"Brand System · Packaging Collection · Flavour Architecture · Campaign Visuals · Retail · Website","description":["Lácteo is a premium gelato concept organised around five regional flavour stories and the visual memory of an Italian summer.","The strategic task was range architecture: make five flavours feel unmistakably related while giving each enough character to stand alone. Violet acts as the master brand colour; yellow typography, waffle-grid geometry and oversized gelato imagery do the navigation work across packaging, retail and digital."],"blocks":[{"type":"image","images":[3],"size":"full","caption":"The full Lácteo Italian gelato collection: five regional flavour stories united by one bold packaging system."},{"type":"text","eyebrow":"Brand idea","title":"Five Italian stories, one unmistakable shelf presence","body":["The collection is built around place as flavour. Amalfi becomes lemon and summer light, Sicily becomes pistachio, Piemonte becomes hazelnut, Venice becomes tiramisu, and Tuscany becomes fig and honey.","Rather than changing the entire pack for each flavour, the system keeps the violet brand block constant and lets ingredient colour, product photography and regional storytelling create variety. The result is cohesive at distance and expressive up close."]},{"type":"pair","variant":"even","images":[2,5],"captions":["Summer Sun & Lemonade: a bright Amalfi-inspired flavour world built around citrus, sea and sun.","Sicilian Pistachio: the same master system translated through softer green gelato tones and ingredient styling."]},{"type":"quote","text":"A Taste of Italy"},{"type":"pair","variant":"even","images":[6,7],"captions":["Piemonte Hazelnut framed through warm nut tones and a northern Italian city atmosphere.","Venetian Tiramisu pairing coffee, cocoa and cream with a romantic Venice setting."]},{"type":"feature","image":8,"imageSide":"right","eyebrow":"Flavour storytelling","title":"A consistent pack that still gives every flavour a world of its own","body":["Each flavour keeps the same core hierarchy: Lácteo wordmark, numbered taste edition, large ingredient-led gelato circles, spoon cue and nutritional badge. This repetition builds recognition across the collection.","The photography around the pack then shifts by flavour, using ingredients and Italian locations to turn a simple tub into a small travel narrative. The Tuscan Fig & Honey edition shows how far the visual tone can move while remaining unmistakably part of the same family."],"caption":"Tuscan Fig & Honey expands the system into warmer sunset tones without losing the violet master identity."},{"type":"image","images":[9],"size":"full","caption":"Open-tub lineup showing how the flavour range works beyond front-facing packaging and reinforces the colour-to-flavour relationship."},{"type":"text","eyebrow":"Retail","title":"Designed for instant recognition in a freezer environment","body":["The retail freezer uses the same saturated violet as a large environmental brand block, helping the range read as one collection even when multiple flavours are merchandised together.","Large gelato imagery and the white Lácteo wordmark carry the identity from individual pack to fixture, making the retail system feel designed rather than merely stocked."]},{"type":"image","images":[1],"size":"full","caption":"Branded freezer presentation turning the packaging language into a strong retail destination."},{"type":"feature","image":0,"imageSide":"left","eyebrow":"Campaign","title":"Italy becomes the campaign architecture","body":["The poster series translates each flavour into a destination-led campaign. Oversized place names, bright skies, ingredient styling and the tub itself create a simple repeatable structure for outdoor, social and point-of-sale communication.","Because the campaign is built from the same flavour logic as the packaging, it feels like an extension of the product rather than a separate advertising layer."],"caption":"Destination campaign posters for Amalfi, Sicily and Venice."},{"type":"feature","image":10,"imageSide":"right","eyebrow":"Digital","title":"A storefront that carries the same appetite and energy","body":["The website extends the collection into a bright editorial shopping experience, using large product cut-outs, Italian landscape photography and the violet-yellow palette at full scale.","The five flavours become the main navigation story, while brand narrative and ingredient content sit underneath as supporting layers. This keeps the digital experience product-first and visually consistent with packaging and campaign."],"caption":"Desktop web direction for the Lácteo Italian Gelato Collection."},{"type":"image","images":[11],"size":"medium","caption":"Macro packaging view highlighting the violet surface, bold typography and product-led circular graphic language."},{"type":"closing","eyebrow":"Concept result","title":"One visual engine across five flavour stories","body":"The final concept uses a small set of repeatable assets to organise the range across tubs, freezer display, campaign and digital. The emphasis is on immediate family recognition first, then flavour-level distinction."}],"cardLine":"Premium gelato · packaging-led brand system"},{"id":"2","slug":"elleye","number":"02","title":"elleye","thumbnail":"./assets/elleye/elleye-01.webp","gallery":["./assets/elleye/elleye-01.webp","./assets/elleye/elleye-02.webp","./assets/elleye/elleye-03.webp","./assets/elleye/elleye-04.webp","./assets/elleye/elleye-05.webp","./assets/elleye/elleye-06.webp","./assets/elleye/elleye-07.webp","./assets/elleye/elleye-08.webp","./assets/elleye/elleye-09.webp","./assets/elleye/elleye-10.webp","./assets/elleye/elleye-11.webp"],"duration":"Independent Brand Project","role":"Venture Concept · Naming · Brand Strategy · Creative Direction · Brand Identity","scope":"Naming · Identity · Packaging · Jewelry Direction · Gifting · Merchandise · Brand Applications","description":["elleye is a self-initiated gifting and accessories venture built around one emotional proposition: a small object can function as a ritual, keepsake and signal of affection.","I shaped the project from venture idea and naming through product logic, identity, jewelry direction, gifting and merchandise. The heart-eye symbol was deliberately tested beyond graphics, so the brand asset could become a physical object rather than simply decorate one."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"The wider elleye brand world across accessories, gifting objects and everyday touchpoints."},{"type":"feature","image":5,"imageSide":"right","eyebrow":"Identity system","title":"One symbol strong enough to carry a whole world","body":["The heart-eye mark became the central asset: expressive enough to act as the main brand symbol, compact enough for a micro mark, and simple enough to move between print, packaging, digital and physical objects.","The identity balances saturated sky blue, hot pink, warm kraft, ivory and metallic gold. The palette gives the brand energy while the typography, spacing and restrained application keep it polished rather than overly sweet."],"caption":"Primary wordmark, logo lockup, colour palette, symbol variants, pattern and application logic."},{"type":"quote","text":"A small gift awaits you."},{"type":"pair","variant":"even","images":[6,7],"captions":["Gold and hot-pink jewelry direction translating the heart-eye into a dimensional product family.","Silver and blue variation showing how the same product language can shift mood without losing recognition."]},{"type":"text","eyebrow":"Product direction","title":"The identity is not simply printed on the product. It can become the product.","body":["A core part of the concept was testing whether the brand symbol could survive outside a flat graphic system. The heart-eye was developed as a pendant, earrings, ring, charms and branded hardware so the identity could be worn, gifted and kept.","That move gives elleye a more ownable commercial territory: the visual identity and the product idea reinforce each other instead of behaving as separate layers."]},{"type":"image","images":[3],"size":"narrow","caption":"Jewelry development: dimensional pendant construction explored from multiple views before moving into the branded product world."},{"type":"feature","image":10,"imageSide":"left","eyebrow":"Jewelry detail","title":"Designed to work at object scale","body":["The close-up product direction focuses on material hierarchy: polished metal, enamel colour, clear stones and the eye detail all need to remain legible at a small physical scale.","The result keeps the playful character of the symbol while giving it enough finish and dimensionality to feel like a real jewelry object rather than a logo-shaped novelty."],"caption":"Close-up heart-eye pendant with enamel, gold-tone metal and clear crystal detailing."},{"type":"pair","variant":"asym-left","images":[4,2],"captions":["Gift packaging system combining kraft, blue pattern, jewelry presentation and the core gifting message.","A softer flower-gifting extension showing how the same language can move into emotional occasions beyond jewelry."]},{"type":"text","eyebrow":"Gifting system","title":"The unboxing had to feel like part of the idea","body":["Packaging is treated as part of the emotional experience rather than a container added at the end. Kraft, blue paper, satin ribbon, gold details and small branded charms create a recognisable ritual without requiring every surface to carry the logo.","The system can flex from a small jewelry box to a larger gift package or flower presentation while keeping the same balance of warmth, optimism and polish."]},{"type":"pair","variant":"even","images":[1,8],"captions":["Tote, sweatshirt and pouch extending the identity into soft merchandise and everyday accessories.","A broader accessory flatlay showing apparel, pouch, keyring and phone charm within one coherent brand language."]},{"type":"image","images":[9],"size":"medium","caption":"Sticker and phone-accessory collection turning the brand language into smaller, collectible expressions."},{"type":"closing","eyebrow":"System logic","title":"One emotional idea, many giftable forms","body":"elleye was built as a brand world rather than a single product. Naming, symbol, packaging, jewelry, gifting and merchandise all support the same promise: small objects with enough personality to feel personal, memorable and worth keeping."}],"cardLine":"Gifting & accessories · venture-to-brand"},{"id":"3","slug":"kitch","number":"03","title":"KITCH","thumbnail":"./assets/kitch/kitch-11-hq.webp","gallery":["./assets/kitch/kitch-01","./assets/kitch/kitch-02","./assets/kitch/kitch-03","./assets/kitch/kitch-04","./assets/kitch/kitch-05","./assets/kitch/kitch-06","./assets/kitch/kitch-07","./assets/kitch/kitch-08","./assets/kitch/kitch-09","./assets/kitch/kitch-10","./assets/kitch/kitch-11","./assets/kitch/kitch-12","./assets/kitch/kitch-13","./assets/kitch/kitch-14"],"duration":"Independent Venture & Brand Project","role":"Venture Concept · Brand Strategy · Creative Direction · Editorial Identity · Digital · Packaging","scope":"Naming · Identity System · Culinary Journal · Recipe Platform · Curated Objects · Ecommerce UX/UI · Packaging · Art Direction","description":["KITCH is a premium culinary platform positioned between editorial culture, practical cooking and collectible kitchen objects.","The venture logic depends on one content architecture serving three behaviours: read, cook and collect. Journal, recipes and objects therefore share the same taxonomy, material language and visual system instead of behaving like separate products under one logo."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"KITCH object world: knife, cookware and serving pieces framed through a precise architectural visual language."},{"type":"feature","image":1,"imageSide":"right","eyebrow":"Editorial ecosystem","title":"A journal that extends naturally into the screen","body":["KITCH combines long-form editorial storytelling with a digital recipe and object experience. The print journal is intentionally slower and more atmospheric, while the mobile layer makes recipes, people and objects immediately usable.","Both formats share the same typography, photography and content taxonomy, so the brand feels continuous rather than split between editorial and commerce."],"caption":"Print journal and mobile platform shown as one connected content system."},{"type":"pair","variant":"asym-left","images":[2,3],"captions":["Material study positioning wood, stone and steel as the visual and conceptual foundation of the object library.","Seasonal KITCH journal covers showing how the identity can flex across food imagery while retaining a disciplined editorial voice."]},{"type":"text","eyebrow":"Brand system","title":"A visual language built from material, proportion and classification","body":["The KITCH wordmark is paired with a quiet technical layer: object numbers, dimensions, maker, origin, temperature, timing and material information. This turns practical data into a recognisable part of the identity rather than secondary metadata.","Warm black, bone white, stainless steel, dark walnut and burnt amber create a palette that feels architectural and tactile. The result is premium without relying on decorative luxury cues."]},{"type":"feature","image":4,"imageSide":"left","eyebrow":"Curated objects","title":"Objects are treated with the same attention as food","body":["Serving pieces, cookware and tools are presented almost as material studies. The photography prioritises form, weight, surface and context, allowing simple kitchen objects to carry the same editorial importance as a finished dish.","This approach supports the commercial layer of KITCH while keeping it inside the broader cultural proposition of the brand."],"caption":"Serving objects placed in a restrained stone-and-water environment to emphasise material character."},{"type":"image","images":[5],"size":"medium","caption":"Object detail page combining product photography, maker information, material specifications and care guidance."},{"type":"pair","variant":"even","images":[6,7],"captions":["Digital home concept separating Journal, Recipes and Objects into distinct but connected editorial territories.","KITCH Object Library imagined as a physical showroom environment, extending the identity into architecture and wayfinding."]},{"type":"quote","text":"Culinary culture in objects."},{"type":"feature","image":8,"imageSide":"right","eyebrow":"Food direction","title":"Food imagery with the same precision as the objects","body":["Recipes are photographed with controlled light, deep material contrast and close attention to texture. The visual direction avoids generic lifestyle brightness in favour of a quieter, more tactile appetite appeal.","The numbered dish system gives food content the same archival logic as the object catalogue, reinforcing one coherent editorial universe."],"caption":"Dish / 014: food art direction built around technique, heat and texture."},{"type":"image","images":[9],"size":"full","caption":"Core identity system: wordmark, taxonomy, numerical coding, typography, grid, graphic device and material palette."},{"type":"feature","image":10,"imageSide":"left","eyebrow":"Packaging system","title":"Retail packaging behaves like part of the archive","body":["Packaging uses the same object codes, dimensions, materials and origin details found throughout the editorial system. Different formats can become dramatically typographic or almost completely quiet without losing recognition.","The system scales from rigid knife boxes and cookware packaging to cards, textile wraps and small object labels, making every purchase feel selected rather than simply stocked."],"caption":"KITCH packaging family for chef knives, cookware, serving objects and specifications."},{"type":"pair","variant":"asym-left","images":[11,12],"captions":["Specification cards, maker information, authenticity material and object tags extend the identity into the smallest practical details.","Shopping bags, protective wrapping and printed collateral translate the system into a refined physical retail experience."]},{"type":"image","images":[13],"size":"narrow","caption":"Macro object branding: engraved KITCH typography, brushed steel and walnut material detail."},{"type":"closing","eyebrow":"Concept result","title":"One system for food, objects and the culture around them","body":"KITCH demonstrates how one strategic premise can organise editorial publishing, recipes, product curation, ecommerce, packaging and environments. The system stays deliberately restrained so the content and objects can change without requiring a new identity each time."}],"cardLine":"Culinary platform · editorial, commerce & objects"},{"id":"4","slug":"cadoo","number":"04","title":"Cadoo","thumbnail":"./assets/cadoo/cadoo-03-1440.webp","gallery":["./assets/cadoo/cadoo-01","./assets/cadoo/cadoo-02","./assets/cadoo/cadoo-03","./assets/cadoo/cadoo-04","./assets/cadoo/cadoo-05","./assets/cadoo/cadoo-06","./assets/cadoo/cadoo-07","./assets/cadoo/cadoo-09","./assets/cadoo/cadoo-10","./assets/cadoo/cadoo-11.webp"],"duration":"Independent Brand Project","role":"Art Direction · Brand Identity · Packaging · Visual System","scope":"Naming · Logo · Mascot · Packaging · Campaign Visuals · Social Media · Brand Applications","description":["Cadoo is a premium cat-care concept centred on a mascot-led packaging system that has to stay warm and expressive without becoming visually chaotic.","The core design problem is scalability. Mascot behaviour, colour coding, information hierarchy and recurring graphic details are treated as modular rules, allowing food, treats, accessories and campaign communication to feel related without repeating one layout."],"blocks":[{"type":"image","images":[1],"size":"full","caption":"Final Cadoo product family with the mascot-led packaging system shown across multiple formats."},{"type":"feature","image":7,"imageSide":"right","eyebrow":"Identity system","title":"A mascot-led identity built as a real brand system","body":["The Cadoo identity begins with a compact wordmark and a character system designed to feel playful without becoming visually chaotic. The mascot is expressive, but the surrounding structure remains clean and commercially usable.","Colour, eye details, linework and recurring graphic symbols create recognition across packaging, communication and product extensions."],"caption":"Brand identity board showing the wordmark, mascot sketches, construction logic, colour palette and core graphic elements."},{"type":"quote","text":"Happy cats. Brighter tomorrows."},{"type":"pair","variant":"asym-left","images":[0,6],"captions":["Sterilised packaging close-up showing the final Chicken & Pomegranate design and print detail.","Front, side and back packaging architecture showing how information hierarchy works across the full pack."]},{"type":"text","eyebrow":"Packaging architecture","title":"Designed as a family, not a set of isolated packs","body":["The system uses a consistent mascot scale, information hierarchy and structural layout while colour separates recipes and functional ranges. This keeps the collection immediately recognisable without making every SKU identical.","Sterilised and non-sterilised products share one visual DNA, with colour coding and supporting labels creating clear navigation between ranges."]},{"type":"feature","image":9,"imageSide":"left","eyebrow":"Range system","title":"Two product lines, one unmistakable visual language","body":["The final range demonstrates how Cadoo can expand across sterilised and non-sterilised formulas while preserving the same core architecture. Colour becomes a practical navigation tool rather than decoration.","The result is a scalable packaging framework that can support new recipes and formats without rebuilding the identity from scratch."],"caption":"Sterilised and non-sterilised packaging lines presented together as one coherent range."},{"type":"pair","variant":"even","images":[2,3],"captions":["Treats, catnip and feeding accessories extending the character system into adjacent product categories.","Collars, feather toy, scratcher and plush accessory translating Cadoo into a wider cat-care ecosystem."]},{"type":"text","eyebrow":"Brand world","title":"The mascot can move from pack to product to campaign","body":["Once the packaging system was established, the same graphic language was extended across accessories, treats, retail communication and digital content. The mascot changes pose and context rather than being repeated as one static sticker.","That flexibility lets the brand remain lively while still feeling controlled and recognisable across very different touchpoints."]},{"type":"image","images":[8],"size":"medium","caption":"Social media direction combining product, ingredients, mascot storytelling and concise brand messaging."},{"type":"feature","image":4,"imageSide":"right","eyebrow":"Campaign direction","title":"Built to stay recognisable at large scale","body":["The campaign language strips the system back to its strongest assets: the wordmark, mascot, pack and a soft architectural environment. At billboard scale, the identity stays legible without needing extra decoration.","This creates a visual world that feels friendly and distinctive while remaining clean enough for commercial outdoor use."],"caption":"Outdoor campaign application translating Cadoo into a simple, high-impact brand-awareness visual."},{"type":"image","images":[5],"size":"medium","caption":"Non-sterilised Salmon & Carrot pack demonstrating the alternate range colour system."},{"type":"closing","eyebrow":"System logic","title":"One visual DNA, many touchpoints","body":"The final Cadoo identity works as a modular system rather than a single packaging template. Wordmark, mascot, colour coding, eye motif and supporting graphics can be recombined across food, treats, accessories, social media and campaign applications without losing the core character of the brand."}],"cardLine":"Cat care · mascot-led packaging system"},{"id":"5","slug":"almonby","number":"05","title":"ALMONBY","thumbnail":"./assets/almonby/almonby-01.avif","gallery":["./assets/almonby/almonby-01.avif","./assets/almonby/almonby-02.avif","./assets/almonby/almonby-03.avif","./assets/almonby/almonby-04.avif","./assets/almonby/almonby-05.avif","./assets/almonby/almonby-06.avif","./assets/almonby/almonby-07.avif","./assets/almonby/almonby-08.avif","./assets/almonby/almonby-09.avif","./assets/almonby/almonby-10.avif","./assets/almonby/almonby-11.avif"],"duration":"Independent Brand Project","role":"Brand Strategy · Creative Direction · Packaging · Digital · Retail","scope":"Brand Identity · Packaging System · Product Art Direction · Website UX/UI · Mobile Routine Experience · Retail Display · Lifestyle Campaign","description":["ALMONBY is a baby-care concept built around everyday routines rather than a single hero product. Packaging, guidance, retail and lifestyle imagery are designed as parts of the same care experience.","The system balances reassurance with visibility: calm editorial structure carries information, while colour separates products and routines. That logic gives the range room to expand without relying on one repeated product lineup or decorative cue."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"The complete ALMONBY care family, establishing the colour-coded packaging system, rounded silhouettes and warm tactile brand world."},{"type":"feature","image":1,"imageSide":"right","eyebrow":"Digital routine","title":"Care translated into a simple daily experience","body":["The mobile experience turns the product range into a guided routine rather than a catalogue. Parents can move from need states such as bath time, dry skin or diaper care into a clear sequence of products and practical guidance.","Soft colour coding, generous spacing and product-first imagery keep the interface friendly and legible while preserving the same calm visual language as the packaging."],"caption":"Mobile routine flow combining need-state navigation, product guidance and daily-care recommendations."},{"type":"pair","variant":"asym-left","images":[2,3],"captions":["Gift presentation extending ALMONBY into a warm, premium gifting moment without losing the everyday softness of the brand.","Lifestyle direction placing the products beside a real parent-and-baby moment so the identity feels lived in rather than purely cosmetic."]},{"type":"text","eyebrow":"Brand system","title":"Softness without disappearing into beige","body":["ALMONBY uses a deliberately brighter product palette inside a warm neutral environment. Blue, pink, green, lavender and coral identify different care needs, while the shared bottle architecture and typographic hierarchy keep the family coherent.","The result is playful enough to feel emotionally relevant to baby care, but structured enough to hold together across packs, ecommerce, app screens, merchandising and campaign photography."]},{"type":"image","images":[4],"size":"narrow","caption":"Silky Baby Oil duo photographed as a luminous product study, showing how colour can remain vivid inside a soft premium environment."},{"type":"feature","image":5,"imageSide":"left","eyebrow":"Ecommerce","title":"A softer editorial alternative to standard baby-care retail","body":["The website combines clear shopping logic with a more editorial rhythm. Ingredient messaging, large product imagery and routine-based navigation create a calmer path through the range than a conventional product grid.","The interface keeps commercial information immediately usable while giving the brand enough space, scale and photography to feel distinctive."],"caption":"Desktop website concept connecting ingredient trust, product discovery and routine-led shopping."},{"type":"pair","variant":"even","images":[6,7],"captions":["Bath-time product grouping using water, bubbles and transparent colour to communicate function without relying on literal instructional graphics.","Soft Baby Lotion hero image focused on texture, pump form and the tactile moisturising benefit of the product."]},{"type":"feature","image":8,"imageSide":"right","eyebrow":"Use context","title":"Products designed around real care moments","body":["The visual system becomes more useful when each product can be shown inside a recognisable moment. Diaper Care is presented alongside the objects already present in the routine, making the communication feel practical without becoming clinical.","This balance between emotional warmth and functional clarity gives the system room to move from campaign imagery into product education."],"caption":"Diaper Care visual placing the product directly inside the changing routine."},{"type":"image","images":[9],"size":"full","caption":"Retail display concept organising the range by care need through sculptural colour zones and a friendly freestanding silhouette."},{"type":"image","images":[10],"size":"medium","caption":"Closing nursery still life showing the blue and pink Silky Baby Oil variants inside the softer everyday world of the brand."},{"type":"closing","eyebrow":"Concept result","title":"A care system organised around routines, not isolated products","body":"The concept connects packaging, ecommerce, mobile guidance, retail display and lifestyle direction through a shared information hierarchy and material tone. The architecture is designed to accommodate future products without rebuilding the brand language."}],"cardLine":"Baby care · packaging, digital & retail"},{"id":"6","slug":"indigo-moss","number":"06","title":"Indigo Moss","thumbnail":"./assets/indigo-moss/indigo-moss-05-1440.webp","gallery":["./assets/indigo-moss/indigo-moss-01","./assets/indigo-moss/indigo-moss-02","./assets/indigo-moss/indigo-moss-03","./assets/indigo-moss/indigo-moss-04","./assets/indigo-moss/indigo-moss-05","./assets/indigo-moss/indigo-moss-06","./assets/indigo-moss/indigo-moss-07"],"duration":"Independent Brand Project","role":"Art Direction · Brand Identity · Packaging · Product Visuals","scope":"Naming Refinement · Identity · Packaging Design · Label System · Bottle & Carton Design · Product Visuals","description":["Indigo Moss is a premium blue-gin concept built around stillness, forest atmosphere and tactile restraint.","Rather than compete through loud category codes, the bottle uses cobalt glass, torn paper, restrained bird symbolism and material contrast to create a quieter point of difference. The case tests how little visual information is needed for the product to retain character across bottle, carton and product imagery."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"Hero presentation establishing the Indigo Moss bottle and carton within a cool atmospheric forest setting."},{"type":"feature","image":6,"imageSide":"right","eyebrow":"Concept development","title":"A spirit shaped by mood, material and place","body":["Indigo Moss began as a packaging concept rooted in atmosphere rather than historical gin clichés. The aim was to create a bottle that feels calm, rare and quietly memorable, something discovered rather than announced.","The concept board explores the essential ingredients of that feeling: cobalt glass, a torn paper edge, subtle bird symbolism, soft natural lettering and a restrained indigo palette inspired by dusk, water and forest shadow."],"caption":"Early concept development connecting the bottle silhouette, bird mark, paper edge and material direction."},{"type":"quote","text":"Nature holds rare beauty."},{"type":"pair","variant":"even","images":[1,5],"captions":["Close-up label view highlighting paper grain, typography and the quiet luxury of the printed surface.","Macro detail focusing on the torn-edge label treatment and the contrast between textured paper and blue glass."]},{"type":"text","eyebrow":"Identity system","title":"Minimal, tactile and recognisable","body":["The identity is intentionally understated. A flowing wordmark gives the bottle elegance, while the serif secondary type and restrained information layout provide structure and credibility.","The small flying-bird mark becomes the key symbolic asset: light, free and natural. Used on the cap and packaging, it adds recognisable character without overwhelming the calm tone of the brand."]},{"type":"pair","variant":"asym-left","images":[2,3],"captions":["Cap detail showing the bird mark, matte closure treatment and simple cord accent.","Reverse bottle and carton presentation demonstrating that the system remains refined from every angle."]},{"type":"feature","image":4,"imageSide":"left","eyebrow":"Brand world","title":"Packaging designed to live beyond the shelf","body":["The visual system extends naturally into serving moments and lifestyle imagery. In the cocktail visual, the bottle holds its presence beside glass, citrus and botanicals without losing its restraint.","That flexibility is important: the packaging needs to feel premium in a retail context, editorial enough for campaign imagery, and clear enough to support a believable product story."],"caption":"Serving scene translating the identity into a refined consumption moment."},{"type":"closing","eyebrow":"Concept result","title":"A spirits identity built through restraint and material contrast","body":"Naming, label architecture, bottle, carton and photography are organised around a narrow sensory territory: indigo glass, paper texture, cool forest references and small symbolic details. The concept is intentionally quiet rather than dependent on decorative luxury cues."}],"cardLine":"Premium gin · packaging & product world"},{"id":"7","slug":"noctra","number":"07","title":"Noctra","thumbnail":"./assets/noctra/noctra-05.webp","gallery":["./assets/noctra/noctra-01.webp","./assets/noctra/noctra-02.webp","./assets/noctra/noctra-03.webp","./assets/noctra/noctra-04.webp","./assets/noctra/noctra-05.webp","./assets/noctra/noctra-06.webp","./assets/noctra/noctra-07.webp","./assets/noctra/noctra-08.webp","./assets/noctra/noctra-09.webp","./assets/noctra/noctra-10.webp"],"duration":"Independent Brand Project","role":"Creative Direction · Brand Identity · Packaging · Campaign Art Direction · Retail Experience","scope":"Logo · Pattern System · Beauty Packaging · Lingerie Direction · Gifting · Editorial Postcards · Retail Interiors","description":["Noctra is a dark-feminine luxury concept spanning beauty, lingerie, gifting and retail.","The challenge is category breadth: cosmetics, garments, objects and interiors need different behaviours, but still need to feel authored by the same brand. Oxblood, black marble, warm gold, the script wordmark and an architectural pattern act as a material and spatial toolkit rather than a fixed template."],"blocks":[{"type":"image","images":[4],"size":"full","caption":"Flagship retail environment translating the Noctra palette, materials, pattern and illuminated wordmark into a complete boutique experience."},{"type":"feature","image":0,"imageSide":"right","eyebrow":"Brand world","title":"A dark-feminine identity built to live beyond packaging","body":["Noctra was designed as a sensual, cinematic luxury system rather than a logo placed on products. Oxblood satin, black marble, cream pattern fields and warm metallic details create a recognisable atmosphere before the wordmark even appears.","The same visual language can move from small accessories to beauty objects and interior spaces without losing its character, giving the brand a larger sense of scale and permanence."],"caption":"Accessories and branded objects extending the identity into tactile lifestyle touchpoints."},{"type":"quote","text":"One visual world across beauty, lingerie, gifting and retail."},{"type":"pair","variant":"asym-left","images":[5,6],"captions":["Beauty range combining packaging, campaign styling and the illustrated anti-Valentine postcard.","Cosmetics close-up showing the palette, mascara and liner as one coherent product family."]},{"type":"text","eyebrow":"Identity system","title":"Pattern, script and materiality do the heavy lifting","body":["The visual system combines a fluid handwritten wordmark with a geometric repeating pattern based on elongated arches and star-like cuts. The contrast gives Noctra both softness and structure.","Across packaging, the pattern is used at different scales and densities rather than repeated mechanically. Deep burgundy surfaces, cream grounds, gold hardware and glossy black accents create hierarchy while keeping every object inside the same luxury universe."]},{"type":"image","images":[7],"size":"narrow","caption":"Editorial postcard series carrying the Noctra voice through bold anti-romantic narratives and a consistent illustrated noir language."},{"type":"feature","image":2,"imageSide":"left","eyebrow":"Beauty packaging","title":"A product language that feels ornamental without becoming decorative","body":["The cosmetic packaging uses sculptural silhouettes, reflective metal and restrained pattern engraving. The identity remains visible at close range through material, proportion and small branded details rather than relying on oversized logos.","That makes the products feel designed as objects in their own right while still reading immediately as part of Noctra."],"caption":"Macro lipstick study focused on metalwork, pattern engraving and the tactile finish of the pack."},{"type":"pair","variant":"even","images":[1,9],"captions":["Lingerie gift set combining burgundy lace, branded hardware, patterned lining and premium packaging.","Close-up lingerie detail showing how the core pattern is translated directly into embroidery and mesh construction."]},{"type":"feature","image":3,"imageSide":"right","eyebrow":"Gifting & retail","title":"The unboxing continues the boutique experience","body":["Shopping bags, rigid boxes, ribbon, tissue and small collateral use the same palette and pattern architecture as the interior. The aim is for the brand experience to remain intact after the customer leaves the store.","The system feels formal enough for luxury gifting while the satin, candlelight and dark floral styling keep the emotional side of the brand present."],"caption":"Retail gifting system staged inside the Noctra boutique environment."},{"type":"image","images":[8],"size":"medium","caption":"Wider lingerie retail scene showing product display, furniture, lighting and brand architecture working as one system."},{"type":"closing","eyebrow":"System logic","title":"A single identity across objects, body and space","body":"Noctra was built as a complete visual ecosystem. Wordmark, pattern, palette, material language and art direction connect beauty products, lingerie, printed matter, gifting and retail interiors without forcing every touchpoint into the same composition."}],"cardLine":"Beauty & lingerie · luxury brand system"},{"id":"8","slug":"fluffy-muffin","number":"08","title":"Fluffy Muffin","thumbnail":"./assets/fluffy-muffin/fluffy-muffin-01.webp","gallery":["./assets/fluffy-muffin/fluffy-muffin-01.webp","./assets/fluffy-muffin/fluffy-muffin-02.webp","./assets/fluffy-muffin/fluffy-muffin-03.webp","./assets/fluffy-muffin/fluffy-muffin-04.webp","./assets/fluffy-muffin/fluffy-muffin-05.webp","./assets/fluffy-muffin/fluffy-muffin-06.webp","./assets/fluffy-muffin/fluffy-muffin-07.webp","./assets/fluffy-muffin/fluffy-muffin-08.webp","./assets/fluffy-muffin/fluffy-muffin-09.webp","./assets/fluffy-muffin/fluffy-muffin-10.webp","./assets/fluffy-muffin/fluffy-muffin-11.webp"],"duration":"Independent Brand Project","role":"Creative Direction · Brand Identity · Packaging · Visual System · Social Media","scope":"Logo · Colour & Type System · Packaging · Retail Touchpoints · Social Media · Branded Applications","description":["Fluffy Muffin is a bakery concept designed around a simple buying moment: a small treat that can brighten an ordinary day.","The identity uses a muffin-shaped wordmark, violet, warm cream and flavour accents to make takeaway packaging immediately legible and cheerful. The system is intentionally simple enough to move from box and cup to retail, menus and social content without becoming a costume."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"Retail hero scene showing the Fluffy Muffin identity across counter presentation, packaging, menu and product display."},{"type":"feature","image":4,"imageSide":"right","eyebrow":"Identity system","title":"A playful identity with a clear visual backbone","body":["The wordmark is built directly into the silhouette of a muffin, turning the logo into both a name and a recognisable brand shape. That compact form gives the identity enough personality to work on boxes, cups, signage and small printed details.","Violet acts as the dominant brand colour, supported by warm cream and flavour accents for raspberry, pistachio and vanilla. A soft wavy pattern adds movement without competing with the logo."],"caption":"Core identity system: logo variants, palette, typography, pattern and material direction."},{"type":"quote","text":"Good muffins. Brighter days."},{"type":"pair","variant":"asym-left","images":[5,3],"captions":["Hero packaging presentation combining the signature violet box, window cut-out and flavour-led product styling.","Close-up pack format showing the branded viewing window and the balance between strong identity and product visibility."]},{"type":"text","eyebrow":"Packaging","title":"Designed to make the product feel like the reward","body":["Packaging is the main stage for the brand. The violet structure creates strong shelf recognition, while transparent windows, warm interiors and restrained copy keep attention on the muffins themselves.","Different box formats share the same visual logic, which makes the system flexible enough for single products, pairs, takeaway sets and gifting without feeling like separate sub-brands."]},{"type":"pair","variant":"even","images":[6,7],"captions":["Macro packaging detail highlighting print finish, logo scale and the subtle wavy pattern.","Smaller takeaway carrier format extending the same visual system into a compact everyday package."]},{"type":"feature","image":9,"imageSide":"left","eyebrow":"Experience","title":"From purchase to unboxing","body":["The inside of the box continues the same brand voice, using colour, tissue pattern and short optimistic phrases to turn opening the package into part of the experience.","The goal was to keep the tone warm and upbeat without making every surface loud. Large brand moments are balanced by quieter materials and simple hierarchy."],"caption":"Open gift box showing the branded interior, tissue system and flavour contrast."},{"type":"text","eyebrow":"Brand applications","title":"The system had to work beyond the bakery box","body":["The visual language extends into cups, aprons, tote bags, cards, liners and printed collateral. Repeating the same few assets at different scales creates recognition without making the applications feel copied and pasted.","This gives Fluffy Muffin a consistent physical presence across staff, takeaway, packaging and customer-facing details while preserving enough variation to keep the world lively."]},{"type":"pair","variant":"asym-left","images":[2,8],"captions":["Branded applications across tote, apron, cups, stationery and takeaway packaging.","Packaging and printed-material flatlay showing how the pattern, logo and colour system work at smaller scales."]},{"type":"feature","image":1,"imageSide":"right","eyebrow":"Social media","title":"A digital expression built from the same ingredients","body":["Social content keeps the product visually central while using the same violet, cream, flavour colours and short copy as the physical brand. This makes the feed feel immediately connected to the in-store experience.","The system is simple enough to support recurring content, but flexible enough for product photography, campaign posts and branded typography without falling into one rigid template."],"caption":"Social media direction connecting product photography, packaging and the brand's optimistic tone."},{"type":"image","images":[10],"size":"medium","caption":"Printed collateral and flavour communication extending the identity into menus, information cards and takeaway moments."},{"type":"closing","eyebrow":"Concept result","title":"A simple identity built around the everyday treat moment","body":"The concept keeps the strongest assets compact: wordmark, violet, warm cream, flavour accents and a soft pattern. Those elements can shift between packaging, retail and social without requiring every application to use the same composition."}],"cardLine":"Bakery · identity, packaging & social"},{"id":"9","slug":"voda-soda","number":"09","title":"VODA SODA","thumbnail":"./assets/voda-soda/voda-soda-05.webp","gallery":["./assets/voda-soda/voda-soda-01.webp","./assets/voda-soda/voda-soda-02.webp","./assets/voda-soda/voda-soda-03.webp","./assets/voda-soda/voda-soda-04.webp","./assets/voda-soda/voda-soda-05.webp","./assets/voda-soda/voda-soda-06.webp","./assets/voda-soda/voda-soda-07.webp","./assets/voda-soda/voda-soda-08.webp","./assets/voda-soda/voda-soda-09.webp","./assets/voda-soda/voda-soda-10.webp","./assets/voda-soda/voda-soda-11.webp","./assets/voda-soda/voda-soda-12.webp"],"duration":"Independent Brand Project","role":"Venture Concept · Brand Strategy · Creative Direction · Packaging · Campaign · Digital","scope":"Naming Direction · Packaging System · Multipack · Retail · Environmental Branding · Campaign · Website","description":["VODA SODA is a self-initiated fruit-beer concept built around a specific summer occasion: cold, colourful cans moving between beach, cooler, shelf and social setting.","Six flavours are organised as one family through typography and pack architecture, while colour does most of the flavour navigation. Multipack, retail, outdoor, environmental and digital applications test whether the product can stay recognisable when the viewing distance and context change."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"VODA SODA fruit-beer family presented as a bright beach-ready product system."},{"type":"feature","image":3,"imageSide":"right","eyebrow":"Packaging system","title":"Six flavours designed to read as one family","body":["Each flavour has its own fruit illustration, colour field and expressive descriptor, while the can architecture stays consistent across the range. That balance gives every SKU personality without breaking recognition at shelf distance.","The visual language combines tactile fruit graphics, oversized flavour typography and a sun-washed palette that feels rooted in Southern California beach culture rather than conventional beer branding."],"caption":"Complete six-flavour can lineup showing the shared hierarchy and individual colour coding."},{"type":"quote","text":"Good Drinks. Brighter Days."},{"type":"pair","variant":"asym-left","images":[9,2],"captions":["Macro can detail showing print texture, condensation, illustration and typographic contrast.","The full flavour family merchandised in a cooler with fruit and ice, showing how the colour system works in a high-energy lifestyle setting."]},{"type":"text","eyebrow":"Brand architecture","title":"Built for flavour navigation and instant shelf recognition","body":["The system uses colour as a practical navigation device: plum blue, cranberry pink, peach coral, pear green, cherry rose and apricot orange. Script descriptors add personality while the heavier flavour names keep the range legible and commercially clear.","Because the composition is modular, the same ingredients can move from single cans to multipacks, retail displays, posters and environmental graphics without becoming a collection of unrelated executions."]},{"type":"feature","image":4,"imageSide":"left","eyebrow":"Multipack","title":"Packaging that turns the range into one object","body":["The six-flavour carrier brings the entire palette together in a single piece of packaging. Large fruit graphics and the bold VODA SODA name create impact from a distance, while the visible cans make the assortment immediately understandable.","The multipack was treated as a brand surface in its own right, not simply a container, so it carries the same sunny, tactile personality as the cans."],"caption":"Six-flavour carrier packaging combining the product range into one high-impact retail object."},{"type":"pair","variant":"even","images":[5,8],"captions":["Dedicated retail display translating the flavour system into a clear shelf-navigation structure.","Refrigerated merchandising showing how the cans hold together in a realistic point-of-sale environment."]},{"type":"feature","image":7,"imageSide":"right","eyebrow":"Environmental branding","title":"A beach-world identity that can occupy physical space","body":["The identity expands beyond packaging into a complete Venice Beach environment, using the sun mark, fruit palette and flavour blocks across umbrellas, signage, a lifeguard structure and cooler graphics.","This makes the brand feel like part of a place and a summer ritual rather than a product that only exists on a shelf."],"caption":"VODA SODA environmental branding applied across a beach activation and lifeguard structure."},{"type":"pair","variant":"asym-left","images":[6,10],"captions":["Lifestyle direction placing the product naturally inside a relaxed beach-day moment.","Outdoor poster series translating individual flavours into bold campaign communication."]},{"type":"feature","image":11,"imageSide":"left","eyebrow":"Digital expression","title":"The same summer energy, organised for the screen","body":["The website keeps the expressive photography and flavour palette, but introduces a clearer editorial hierarchy for discovery, navigation and product browsing.","Large campaign imagery creates the emotional entry point, while modular flavour cards and location content turn the brand world into a usable consumer experience."],"caption":"Desktop website concept combining campaign storytelling, flavour navigation and find-near-you functionality."},{"type":"image","images":[1],"size":"medium","caption":"Brand world combining poster communication, core cans and multipack packaging in one beach-side composition."},{"type":"closing","eyebrow":"Concept result","title":"A colourful system built around a clear summer occasion","body":"The concept connects product family, multipack, retail, campaign, environmental branding and digital through a consistent pack architecture and flavour-colour logic. The point is not to repeat one composition, but to preserve recognition as the context changes."}],"cardLine":"Fruit beer · product family, retail & campaign"},{"id":"10","slug":"lushy","number":"10","title":"LUSHY","thumbnail":"./assets/lushy/lushy-08-1440.webp","gallery":["./assets/lushy/lushy-01","./assets/lushy/lushy-02","./assets/lushy/lushy-03","./assets/lushy/lushy-04","./assets/lushy/lushy-05","./assets/lushy/lushy-06","./assets/lushy/lushy-07","./assets/lushy/lushy-08","./assets/lushy/lushy-09"],"duration":"Independent Brand Project","role":"Art Direction · Brand Identity · Packaging · Website · Campaign Visuals","scope":"Identity · Packaging System · Product Imagery · Social Media · Web Design · Brand Applications","description":["LUSHY is a premium skincare concept organised around luminosity, material clarity and a cool, high-gloss visual world.","The system uses reflective blues, translucent forms, cream textures and controlled product imagery to create a consistent sensory direction across packaging, web and campaign. The intended effect is polished and premium without relying on dense clinical language or decorative luxury."],"blocks":[{"type":"image","images":[0],"size":"full","caption":"Website hero presentation showing the desktop and mobile experience within the wider LUSHY visual world."},{"type":"feature","image":1,"imageSide":"right","eyebrow":"Concept","title":"A luminous skincare world","body":["LUSHY was developed as a beauty concept that feels bright, refined and sensorial. The aim was to create a skincare identity that communicates glow and clarity while keeping the overall system minimal, premium and commercially believable.","Instead of relying on busy beauty clichés, the art direction uses controlled light, soft gradients and reflective forms to create a more elevated and immersive brand atmosphere."],"caption":"Social media direction combining product focus, reflective surfaces and clean editorial framing."},{"type":"quote","text":"A beauty identity built around purity, luminosity and elevated simplicity."},{"type":"pair","variant":"asym-left","images":[2,3],"captions":["Macro packaging detail emphasising typography, print finish, texture and the tactile side of the identity.","Cream facial mask hero composition using sculptural product texture and glass elements to reinforce the sensorial skincare story."]},{"type":"text","eyebrow":"Visual system","title":"Clean structure, sensorial impact","body":["The identity balances restraint with visual richness. A compact typographic system, strong product silhouettes and a focused colour palette keep the packaging and digital touchpoints coherent, while lighting, glossy reflections and material contrasts add desirability.","This balance allows the brand to move between product information, e-commerce clarity and campaign expression without losing its premium beauty-market tone."]},{"type":"image","images":[4],"size":"narrow","caption":"Packaging architecture focused on the box structure, gradient finish and clear hierarchy of information."},{"type":"feature","image":5,"imageSide":"left","eyebrow":"Art direction","title":"Glow, fluidity and material beauty","body":["Across the project, imagery is built around a luminous blue environment, transparent glass shapes, liquid reflections and smooth cream textures. Together these elements make the products feel both futuristic and tactile.","The product remains the focal point in every frame. Decorative material is used to support the skincare story rather than compete with it, keeping the compositions polished and commercially usable."],"caption":"Cleansing-foam hero visual using soft foam forms and a more sculptural editorial mood."},{"type":"pair","variant":"even","images":[6,7],"captions":["Hydrating-face-tonic visual using circular refraction and water ripples to communicate freshness and clarity.","The wider product family presented as a coherent system of silhouettes, finishes and blue-to-white gradients."]},{"type":"text","eyebrow":"Digital expression","title":"Designed to move between product and campaign","body":["The same visual language extends into website design and social media, where luminous product imagery carries the emotional side of the brand while the UI remains clean and easy to navigate.","That separation of roles gives LUSHY flexibility: the digital system can stay functional and restrained while campaign imagery supplies the depth, texture and atmosphere."]},{"type":"image","images":[8],"size":"medium","caption":"Closing brand visual bringing logo, environment and product cues together in one polished final frame."},{"type":"closing","eyebrow":"Concept result","title":"A skincare system organised around light, material and clarity","body":"Identity, packaging, web and campaign imagery share the same material logic rather than one repeated layout. The concept can extend to future products by preserving the balance of luminous blue, transparent surfaces, clear hierarchy and controlled product photography."}],"cardLine":"Skincare · identity, packaging & digital"}];
const app=document.getElementById("app");
function esc(s){return String(s).replace(/[&<>"\']/g,function(m){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","\'":"&#039;"}[m]})}

function trimSlashes(s){
  s=String(s||"");
  while(s.charAt(0)==="/") s=s.slice(1);
  while(s.length&&s.charAt(s.length-1)==="/") s=s.slice(0,-1);
  return s;
}
function currentRoute(){
  var p=decodeURIComponent(location.pathname||"/");
  var marker="/preview/";
  var at=p.indexOf(marker);
  var rel=at>=0?p.slice(at+marker.length):p;
  rel=trimSlashes(rel);
  if(rel.slice(-10).toLowerCase()==="index.html") rel=rel.slice(0,-10);
  return trimSlashes(rel);
}
function routeHref(route){
  route=trimSlashes(route||"");
  return route?route+"/index.html":"index.html";
}
function routeLink(route,label,cls){return '<a href="'+routeHref(route)+'"'+(cls?' class="'+cls+'"':'')+'>'+label+'</a>'}
function contactEmail(){
  var codes=[97,108,101,107,115,97,110,100,114,97,46,105,97,103,111,118,107,105,110,97,64,103,109,97,105,108,46,99,111,109];
  return codes.map(function(n){return String.fromCharCode(n)}).join("");
}
function emailLink(label,cls){
  return '<a href="#" data-contact-email="1" aria-label="Email Aleksandra Iagovkina"'+(cls?' class="'+cls+'"':'')+'>'+label+'</a>';
}
function nav(){
  var h=currentRoute();
  function item(route,label,cls){
    var active=h===route||(route==="work"&&h.indexOf("work/")===0);
    var classes=((cls||"")+(active?" is-active":"")).trim();
    return '<a href="'+routeHref(route)+'"'+(classes?' class="'+classes+'"':'')+(active?' aria-current="page"':'')+'>'+label+'</a>';
  }
  return '<header class="target-header"><div class="target-header-inner"><a href="'+routeHref("")+'" class="target-brand" aria-label="Aleksandra Iagovkina — Home"><img src="./assets/logo.png" alt="" class="target-brand-mark"/></a><nav class="target-nav" aria-label="Primary">'+item("services","Services")+item("method","Method")+item("work","Work")+item("about","About")+item("start-a-project","Start a conversation","nav-cta")+'</nav><button class="target-menu-toggle" type="button" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></div><div class="mobile-menu" id="mobile-menu" aria-hidden="true"><div class="mobile-menu-inner"><div class="mobile-menu-kicker">Venture-to-Brand Strategist · Creative Director</div><nav class="mobile-menu-nav" aria-label="Mobile navigation">'+item("services","Services")+item("method","Method")+item("work","Work")+item("about","About")+item("start-a-project","Start a conversation")+'</nav><div class="mobile-menu-meta">'+emailLink("Email")+'<span>Venture Shaping · Strategy · Brand</span></div></div></div></header>'
}
function footer(){return '<footer class="site-footer"><div class="site-footer-inner"><div class="site-footer-left"><div class="site-footer-title">Aleksandra Iagovkina</div><div class="site-footer-sub">Venture-to-Brand Strategist · Creative Director</div></div><nav class="site-footer-nav" aria-label="Footer navigation">'+routeLink("services","Services")+routeLink("method","Method")+routeLink("work","Work")+routeLink("about","About")+routeLink("terms","Terms")+routeLink("privacy","Privacy")+'</nav><div class="site-footer-right">'+emailLink("Email")+'</div></div></footer>'}

function projectCard(p){var crispThumb=p.slug==="cadoo"||p.slug==="lushy"||p.slug==="voda-soda"||p.slug==="indigo-moss"||p.slug==="kitch";var imgClass=crispThumb?"work-image work-image--cadoo":"work-image";var media=p.thumbnail?'<img class="'+imgClass+'" src="'+p.thumbnail+'" alt="'+esc(p.title)+'" width="1200" height="675" loading="lazy" decoding="async" fetchpriority="low"/>':'<div class="work-placeholder"><span>'+p.number+'</span><strong>'+esc(p.title)+'</strong><small>Visual coming soon</small></div>';return '<a href="'+routeHref("work/"+p.slug)+'" class="work-card"><div class="work-media">'+media+'</div><div class="work-meta"><div><h3 class="work-title">'+esc(p.title)+'</h3><div class="work-card-sub">'+esc(p.cardLine||"Self-initiated venture & brand concept")+'</div></div><div class="work-num">'+p.number+'</div></div></a>'}
function cardsMarkup(items){return items.map(projectCard).join("")}
function home(){
  return nav()+'<main class="route-fade home-page">'+
  '<section class="hero-target hero-target--strategy hero-home-v4"><div class="hero-target-inner"><div class="hero-kicker">Aleksandra Iagovkina · Venture-to-Brand Strategist · Creative Director</div><div class="hero-stage-v4"><img class="hero-ref-blob" src="./assets/decor/hero-red-shape.avif" width="1600" height="1600" alt="" aria-hidden="true"/><img class="hero-ref-stars hero-ref-stars--left" src="./assets/decor/stars-b.webp" width="83" height="68" alt="" aria-hidden="true"/><img class="hero-ref-stars hero-ref-stars--right" src="./assets/decor/stars-a.webp" width="64" height="106" alt="" aria-hidden="true"/><div class="hero-copy-v4"><h1>Define what is worth building</h1><div class="hero-signature-v4"><p>I help turn experience, strengths and real constraints into a venture direction, then carry that direction into a coherent brand.</p></div><div class="hero-actions hero-actions--primary">'+routeLink("start-a-project","Start a conversation","btn-primary")+routeLink("work","View selected work","btn-secondary")+'</div></div></div><div class="hero-foot-v4"><div class="hero-mini-label">12+ years in professional graphic design</div><p>You can come before the brief, before the business model, or with an existing venture that needs a clearer next chapter.</p><div class="hero-foot-actions">'+routeLink("method","Explore the method","text-link")+'</div></div></div></section>'+
  '<section class="editorial-section audience-section"><div class="editorial-inner"><div class="editorial-head"><div class="editorial-kicker">Where the work begins</div><div><h2>You already have something to build from</h2><p class="editorial-lead">The starting point can be experience, several possible directions, an early idea, or a business that no longer feels clear.</p></div></div><div class="stage-grid"><div class="stage-card"><div class="num">01 · No clear venture yet</div><h3>I want something of my own, but I do not know what</h3><p>We look at strengths, experience, recurring patterns, resources and the kind of working life the venture needs to support.</p></div><div class="stage-card"><div class="num">02 · Several directions</div><h3>I can see more than one possible path</h3><p>We compare the options against personal fit, practical constraints, commercial logic and long-term sustainability.</p></div><div class="stage-card"><div class="num">03 · Early venture</div><h3>I have an idea, but it is not a business yet</h3><p>We shape the offer, audience, business format and position before investing in the visual layer.</p></div><div class="stage-card"><div class="num">04 · Existing business</div><h3>The next direction is no longer obvious</h3><p>We identify what should remain, what has become noise and what the next chapter needs to become.</p></div></div></div></section>'+
  '<section class="editorial-section offer-section accent-section--ivory"><div class="editorial-inner"><div class="editorial-head"><div class="editorial-kicker">Ways to work together</div><div><h2>One path. Different depths.</h2><p class="editorial-lead">The scope follows the question. It does not automatically expand into a full identity, website or production retainer.</p></div></div><div class="service-grid service-ladder"><div class="service-card service-card--entry"><div class="num">01 · Start here</div><h3>Venture Diagnostic</h3><p>Clarify what is worth building next and why.</p></div><div class="service-card"><div class="num">02</div><h3>Venture Shaping</h3><p>Turn the direction into an offer, audience, business format and position.</p></div><div class="service-card"><div class="num">03</div><h3>Venture-to-Brand</h3><p>Translate the venture into naming, narrative, identity and key launch touchpoints.</p></div><div class="service-card"><div class="num">04</div><h3>Creative Direction</h3><p>Guide the next stage of an existing brand without turning the work into endless production.</p></div></div><p class="offer-range-note">Engagements range from focused strategic diagnostics to complete venture-to-brand projects.</p>'+routeLink("services","Explore services","text-link")+'</div></section>'+
  '<section class="editorial-section method-home-section"><div class="editorial-inner"><div class="editorial-head"><div class="editorial-kicker">The method · Venture Shaping</div><div><h2>Strategy before aesthetics</h2><p class="editorial-lead">The brand is the visible result of a decision. First we understand what is already true, choose the direction and pressure-test the venture logic.</p></div></div><div class="path-grid"><div class="path-step"><div class="path-num">01</div><h3>Person</h3><p>Strengths, experience, patterns, resources and constraints</p></div><div class="path-step"><div class="path-num">02</div><h3>Direction</h3><p>The decision: what is actually worth building</p></div><div class="path-step"><div class="path-num">03</div><h3>Venture</h3><p>Offer, audience, business format and commercial logic</p></div><div class="path-step"><div class="path-num">04</div><h3>Position</h3><p>A clear reason to exist and a place in the market</p></div><div class="path-step"><div class="path-num">05</div><h3>Brand</h3><p>Name, narrative, identity and key touchpoints</p></div><div class="path-step"><div class="path-num">06</div><h3>Next chapter</h3><p>A system that can evolve without losing its core</p></div></div><div class="method-note method-note--important"><div class="editorial-kicker">Optional reflective layer</div><p>Natal astrology can be used as one additional lens on recurring motivations and working patterns. It never replaces research, strategic judgment, financial reality or common sense.</p></div>'+routeLink("method","Explore Venture Shaping","text-link")+'</div></section>'+
  '<section class="editorial-section proof-section"><div class="editorial-inner"><div class="editorial-head"><div class="editorial-kicker">Selected work</div><div><h2>Ventures built before the brief existed</h2><p class="editorial-lead">Self-initiated concepts developed from business idea and naming through positioning, identity and visual direction.</p></div></div><div class="work-grid">'+cardsMarkup(projects.slice(0,4))+'</div><div class="work-note"><div class="editorial-kicker">Why self-initiated?</div><div><p>They are not presented as client commissions. <span>My earlier commercial work was largely shaped by existing briefs and client direction; these concepts show how I think when I own the brief, the strategic decisions and the visual system end to end.</span></p>'+routeLink("work","View all 10 ventures","text-link")+'</div></div></div></section>'+
  '<section class="editorial-section home-about-section"><div class="editorial-inner about-preview about-preview--portrait"><div class="about-page-hero-visual home-about-approved"><img class="about-composite-image" src="./assets/decor/portrait-composite.avif" width="1600" height="1550" alt="Aleksandra Iagovkina" loading="lazy" decoding="async"/></div><div class="about-preview-copy"><div class="editorial-kicker">About</div><h2>A thinking partner with a designer&#39;s hands</h2><p>My background is 12+ years in professional graphic design, including senior-level in-house and freelance work. This practice moves me earlier in the process, where the brief, the venture and the brand direction are still being shaped.</p><p class="small">The value is not more deliverables. It is seeing the pattern, making the decision and carrying that decision into a brand people can understand.</p>'+routeLink("about","About Aleksandra","text-link")+'</div></div></section>'+
  '<section class="editorial-section cta-panel"><div class="editorial-inner"><div class="editorial-kicker">Start a conversation</div><h2>Bring the situation<br/>not a perfect brief</h2><p>Tell me what is changing, what you already have and what you are trying to decide.</p>'+routeLink("start-a-project","Start a conversation","btn-primary")+'</div></section>'+
  '</main>'+footer()
}

function workPage(){return nav()+'<main class="page-view route-fade work-page"><div class="page-shell"><div class="page-kicker">Work</div><h1 class="page-title">Selected Ventures</h1><div class="page-intro"><div class="editorial-kicker">10 self-initiated venture concepts</div><p>Each case begins before the visual identity: with the question of what should exist, for whom and why. <span class="muted">These are self-initiated concepts, not client commissions.</span></p></div><div class="work-grid">'+cardsMarkup(projects)+'</div><div class="work-note"><div class="editorial-kicker">What the portfolio demonstrates</div><div><p>I can create the brief, not only execute one. <span>Across these concepts, the venture idea, naming, positioning and visual system are decisions I own from the start.</span></p></div></div></div></main>'+footer()}

function servicesPage(){return nav()+'<main class="page-view route-fade services-page"><div class="page-shell"><div class="page-kicker">Services</div><h1 class="page-title">Start With the Question</h1><div class="page-intro"><div class="editorial-kicker">One practice · different depths</div><p>You do not need to choose a service before we talk. Tell me where you are now and I will suggest the depth of work that makes sense.</p></div>'+
'<section class="service-detail service-detail--entry"><h3>Venture Diagnostic</h3><div class="service-detail-copy"><p>For someone who wants to build something of their own, is at a professional turning point, or can see several possible directions but does not yet know which one deserves further development.</p><div class="deliverables"><span class="pill">Deep consultation</span><span class="pill">Experience · strengths · asset mapping</span><span class="pill">Motivations &amp; working patterns</span><span class="pill">Constraints &amp; priorities</span><span class="pill">Optional natal-astrology layer</span><span class="pill">Potential directions</span><span class="pill">Direction blueprint</span></div><div class="service-format"><span>Typical format</span><strong>One focused working session + written direction blueprint</strong><small>Usually completed within 1 week. Exact timing is confirmed before we start.</small></div><div class="investment-line"><span>Typical investment</span><strong>From €650</strong></div></div></section>'+
'<section class="service-detail"><h3>Venture Shaping</h3><div class="service-detail-copy"><p>For a promising direction that is not yet a clear business. We turn the idea into a venture with enough definition to test, explain and build.</p><div class="deliverables"><span class="pill">Venture concept</span><span class="pill">Audience</span><span class="pill">Offer</span><span class="pill">Business format</span><span class="pill">Positioning</span><span class="pill">Differentiation</span><span class="pill">Testing priorities</span><span class="pill">Development direction</span></div><div class="service-format"><span>Typical format</span><strong>Multi-session strategic engagement</strong><small>Typically 2–4 weeks, depending on the number of directions and decisions to test.</small></div><div class="investment-line"><span>Typical investment</span><strong>From €1,800</strong></div></div></section>'+
'<section class="service-detail service-detail--flagship"><h3>Venture-to-Brand</h3><div class="service-detail-copy"><p>The flagship engagement. It takes a strategic direction into a coherent brand, carrying the logic of the venture through the story, identity and the touchpoints it actually needs.</p><div class="deliverables"><span class="pill">Concept</span><span class="pill">Positioning</span><span class="pill">Naming</span><span class="pill">Brand narrative</span><span class="pill">Brand strategy</span><span class="pill">Core visual identity</span><span class="pill">Creative direction</span><span class="pill">Selected digital / packaging / launch touchpoints</span></div><div class="service-format"><span>Typical format</span><strong>Core strategy + brand-system engagement</strong><small>Typically 6–10 weeks. From €4,500 covers the strategic foundation and core brand system; extended website systems, packaging ranges, campaigns or production are scoped separately.</small></div><div class="investment-line"><span>Typical investment</span><strong>From €4,500</strong></div></div></section>'+
'<section class="service-detail"><h3>Creative Direction</h3><div class="service-detail-copy"><p>For an existing venture or brand that needs ongoing high-level direction or a clearly defined next stage, without turning the relationship into an open-ended production retainer.</p><div class="deliverables"><span class="pill">Campaign direction</span><span class="pill">Website direction</span><span class="pill">Packaging direction</span><span class="pill">Brand-system extension</span><span class="pill">Launch review</span><span class="pill">Selected high-value design work</span></div><div class="service-format"><span>Typical format</span><strong>Project-based or advisory</strong><small>Scope, cadence and timing are agreed around a defined stage or decision.</small></div><div class="investment-line"><span>Investment</span><strong>Scoped individually</strong></div></div></section>'+
'<section class="services-investment-note"><div class="editorial-kicker">How scope is set</div><div><p>Final scope, timing and investment depend on the stage of the venture, complexity and required deliverables.</p><p>You do not need to choose the right engagement yourself. The first conversation is there to determine what depth of work is actually useful.</p></div></section>'+
'<section class="support-detail"><h3>Optional natal astrology</h3><div><p>If useful, it can be included in the discovery stage as an additional reflective framework for recurring strengths, motivations and working patterns.</p><p>It does not replace research, psychology, financial reality, strategic judgment or common sense.</p></div></section>'+
'<section class="page-section statement-section"><div class="statement-layout"><div class="editorial-kicker">Scope &amp; boundaries</div><div><h2 class="statement-title">Clear ownership<br/>clean handoffs</h2><p class="statement-copy">I lead the strategy, brand system and key design work. Specialist production is handed to the appropriate expert when the project needs it.</p></div></div><div class="scope-grid"><div class="scope-card"><h3>What I handle</h3><div class="scope-list"><div class="scope-item">Deep consultation, strengths and pattern analysis</div><div class="scope-item">Business direction, venture concept, offer and audience</div><div class="scope-item">Positioning, naming and brand narrative</div><div class="scope-item">Identity, website UX/UI, packaging and print</div><div class="scope-item">Production-ready artwork for agreed print deliverables</div><div class="scope-item">Communication with the client&#39;s chosen print house</div></div></div><div class="scope-card"><h3>Specialist handoff</h3><div class="scope-list"><div class="scope-item">Website coding and development</div><div class="scope-item">3D modelling and specialist CGI</div><div class="scope-item">Complex animation production</div><div class="scope-item">Print-house sourcing and procurement</div></div></div></div><div class="scope-cta">'+routeLink("start-a-project","Discuss your situation","btn-primary")+'</div></section>'+
'</div></main>'+footer()}
function methodPage(){var steps=[["01","Read what already exists","Experience, strengths, recurring patterns, motivations, resources, limits and preferred way of working."],["02","Name the real question","What is changing, what no longer fits, and what the next chapter actually has to solve."],["03","Build possible directions","Generate paths from real assets rather than from trends or category imitation."],["04","Choose the direction","Compare the options against personal fit, commercial logic, feasibility and sustainability."],["05","Shape the venture","Define the offer, audience, format, position and the assumptions that need testing."],["06","Test the logic","Pressure-test usefulness, differentiation, feasibility and commercial sense."],["07","Build the brand","Translate the strategic idea into naming, narrative, identity and the key touchpoints the venture needs."],["08","Define the next chapter","Set launch priorities and a growth direction without overbuilding the system."]];return nav()+'<main class="page-view route-fade method-page"><div class="page-shell"><div class="page-kicker">Method</div><h1 class="page-title method-name-title">Venture Shaping</h1><div class="method-title-flow" aria-label="Person to Direction to Venture to Brand"><div class="method-title-row method-title-row--single"><span>Person</span><span class="method-flow-arrow">→</span><span>Direction</span><span class="method-flow-arrow">→</span><span>Venture</span><span class="method-flow-arrow">→</span><span>Brand</span></div></div><div class="page-intro"><div class="editorial-kicker">The principle</div><p>The work starts before branding: with the decision about what is actually worth building.</p></div><section class="method-journey" aria-label="Eight-step method"><div class="method-journey-line" aria-hidden="true"></div>'+steps.map(function(s,i){var side=i%2===0?"left":"right";var phase=i<4?"read":"build";var step='<article class="method-step method-step--'+side+' method-step--'+phase+'"><div class="method-step-content"><div class="method-step-label">Step '+s[0]+'</div><h3>'+s[1]+'</h3><p>'+s[2]+'</p></div><div class="method-step-node" aria-hidden="true"><span>'+s[0]+'</span></div></article>';if(i===3){step+='<div class="method-decision-gate"><span>Decision gate</span><strong>Choose what is worth carrying forward</strong><p>Person and direction become a venture only after the logic is strong enough to commit to.</p></div>'}return step}).join("")+'</section><section class="quote-break quote-break--compact"><div class="quote-break-inner"><blockquote>Decide what is worth building<br/>then make it visible</blockquote></div></section><section class="page-section method-astro-section"><div class="astrology-box"><h3>An optional reflective layer, not the business case</h3><div><p>When useful, natal astrology can add another lens on recurring motivations, tensions and working patterns.</p><p>It does not choose the venture, predict commercial success or replace research. The final direction still has to make sense in practical and strategic terms.</p></div></div></section><section class="page-section statement-section"><div class="statement-layout"><div class="editorial-kicker">The outcome</div><div><h2 class="statement-title">A direction you can explain<br/>defend and build</h2><p class="statement-copy">The goal is enough clarity to commit, enough logic to test and enough character to become a distinctive brand.</p>'+routeLink("start-a-project","Start a conversation","btn-primary")+'</div></div></section></div></main>'+footer()}

function aboutPage(){return nav()+'<main class="page-view route-fade about-page"><div class="page-shell"><section class="about-page-hero"><div class="about-page-hero-copy"><div class="page-kicker">About</div><h1 class="page-title">Aleksandra Iagovkina</h1><p class="about-hero-role">Venture-to-Brand Strategist · Creative Director</p></div><div class="about-page-hero-visual"><img class="about-composite-image" src="./assets/decor/portrait-composite.avif" width="1600" height="1550" alt="Aleksandra Iagovkina" loading="eager" decoding="async"/></div></section><div class="about-story"><div class="about-story-label">Why this practice exists</div><div class="about-story-copy"><p>My background is 12+ years in professional graphic design, including senior-level in-house and freelance work. Much of that career was spent working inside briefs that had already been defined. Over time, the question that interested me most became not only “what should this brand look like?” but “what is actually worth building, and why?”</p><p class="small">This practice is a new chapter built on that experience. I now work earlier in the process, using a designer’s understanding of brands, audiences and execution to help shape the direction, venture logic, positioning and brand before the work is reduced to deliverables.</p><p class="small">The self-initiated ventures on this site are intentional: they show what happens when I am responsible for the brief as well as the outcome, from the initial idea and positioning through to the visual system.</p></div></div><section class="about-proof"><div class="about-proof-item"><span>12+ years</span><strong>Professional graphic design</strong></div><div class="about-proof-item"><span>Senior-level</span><strong>In-house experience</strong></div><div class="about-proof-item"><span>Independent</span><strong>Freelance practice</strong></div><div class="about-proof-item"><span>Across formats</span><strong>Brand identity · digital · print · packaging</strong></div></section><section class="about-commercial"><div class="about-story-label">Selected commercial context</div><div class="about-commercial-body"><p class="about-commercial-lead">Earlier commercial work includes projects involving international brands and organisations across very different markets.</p><div class="brand-word-grid" aria-label="Selected brands"><span>Gaggenau</span><span>Puma</span><span>Siemens</span><span>Bosch</span><span>Lukoil</span><span>Allianz</span></div><div class="commercial-meta"><div><span>Geography</span><strong>Clients, teams and projects across most continents</strong></div><div><span>Sectors</span><strong>Banking · Insurance · Sports · Public sector · FMCG · Television</strong></div></div><p class="about-commercial-note">The categories and markets changed; the constant was learning how very different organisations turn complex requirements into something people can understand and use.</p></div></section><section class="page-section accent-section accent-section--ivory about-philosophy"><div class="page-section-head"><div class="editorial-kicker">How I think</div><div><h2>Clarity is not simplification</h2><p>Good strategy does not erase complexity. It finds the pattern inside it and makes the next decision possible.</p></div></div><div class="value-grid"><div class="value-card"><div class="num">01</div><h3>Pattern recognition</h3><p>I look for strengths, contradictions and assets that are easy to miss from inside your own situation.</p></div><div class="value-card"><div class="num">02</div><h3>Strategic synthesis</h3><p>Personal fit, market logic, resources and constraints have to resolve into one coherent direction.</p></div><div class="value-card"><div class="num">03</div><h3>Creative translation</h3><p>The reasoning should remain visible in the name, story, identity, interface, packaging and other key touchpoints.</p></div><div class="value-card"><div class="num">04</div><h3>Selective execution</h3><p>I stay close to the decisions that matter and hand off specialist production where it belongs.</p></div></div></section><section class="page-section statement-section about-role-section"><div class="statement-layout"><div class="editorial-kicker">The role</div><div><h2 class="statement-title">A thinking partner<br/>with a designer&#39;s hands</h2><p class="statement-copy">The advantage of working across strategy and creative direction is continuity. The reasoning does not disappear when the design begins.</p>'+routeLink("start-a-project","Start a conversation","btn-primary")+'</div></div></section></div></main>'+footer()}

function startPage(){return nav()+'<main class="page-view route-fade start-page"><div class="page-shell"><div class="page-kicker">Start a conversation</div><h1 class="page-title">Bring the Situation</h1><div class="page-intro"><div class="editorial-kicker">No perfect brief required</div><p>Tell me what is changing, what you already have to work with and what you are trying to decide.</p></div><div class="start-layout"><div class="start-copy"><h2>What are you trying to figure out?</h2><p>You do not need to choose the service yourself. Tell me where you are now and I will suggest the depth of work that makes sense.</p><div class="start-investment"><div class="editorial-kicker">Investment guidance</div><p>Focused Venture Diagnostics begin at €650. Venture Shaping begins at €1,800. Venture-to-Brand begins at €4,500 for the strategic foundation and core brand system; extended digital, packaging, campaign or production scope is quoted separately. Creative Direction is scoped individually.</p><small>These are starting points, not automatic package prices. Final scope, timing and investment are confirmed in writing before any paid work begins.</small></div><p>If you prefer, you can contact me directly.</p><div class="start-links">'+emailLink("Email")+'</div><p class="scope-note">I lead strategy, brand direction and key design work. Specialist production is handed off when needed. Sending an enquiry does not create a booking or contract; work begins only after scope, timing and payment terms are agreed in writing. '+routeLink("terms","Read client information","text-link")+'</p></div><form class="project-form project-form--simple" id="project-form"><div class="form-field"><label for="pf-name">Name</label><input id="pf-name" name="name" autocomplete="name" required/></div><div class="form-field"><label for="pf-email">Email</label><input id="pf-email" name="email" type="email" autocomplete="email" required/></div><div class="form-field"><label for="pf-stage">Where are you now?</label><select id="pf-stage" name="stage"><option value="Not sure yet">Not sure yet</option><option value="No clear venture yet">No clear venture yet</option><option value="Several possible directions">Several possible directions</option><option value="Early venture or idea">Early venture or idea</option><option value="Existing business or brand">Existing business or brand</option></select></div><div class="form-field"><label for="pf-budget">Approximate investment range</label><select id="pf-budget" name="budget"><option value="Not sure yet">Not sure yet</option><option value="Under €1,000">Under €1,000</option><option value="€1,000–€2,500">€1,000–€2,500</option><option value="€2,500–€5,000">€2,500–€5,000</option><option value="€5,000–€10,000">€5,000–€10,000</option><option value="€10,000+">€10,000+</option></select></div><div class="form-field form-field--full"><label for="pf-decision">What are you trying to figure out?</label><textarea id="pf-decision" name="decision" placeholder="The situation, options or uncertainty you are dealing with."></textarea></div><div class="form-field form-field--full"><label for="pf-assets">What do you already have to build from?</label><textarea id="pf-assets" name="assets" placeholder="Experience, skills, audience, existing business, network, resources, ideas, constraints..."></textarea></div><div class="form-field form-field--full"><label for="pf-details">Timing, links or anything else useful</label><textarea id="pf-details" name="details" placeholder="Website, current brand, preferred timing or other context."></textarea></div><button type="submit" class="btn-primary form-submit">Open email draft</button><div class="form-note">This opens your email client with the message pre-filled. Nothing is uploaded or stored by this page. See the '+routeLink("privacy","Privacy Policy")+' for how contact information is handled.</div></form></div></div></main>'+footer()}
function privacyPage(){return nav()+'<main class="page-view route-fade privacy-page"><div class="page-shell"><div class="page-kicker">Legal</div><h1 class="page-title">Privacy Policy</h1><div class="page-intro"><div class="editorial-kicker">Standalone practice</div><p>This policy applies only to this Venture-to-Brand Strategy and Creative Direction website and to enquiries or engagements initiated through it. It does not apply to any other website, project, brand, business or service.</p></div><div class="privacy-layout"><aside class="privacy-aside"><strong>Last updated</strong>29 September 2026<br/><br/><strong>Controller</strong>Aleksandra Iagovkina<br/>Self-employed individual · Russian Federation<br/>'+emailLink("Email via this site")+'</aside><div class="privacy-copy"><section class="privacy-section"><h2>What information I may receive</h2><p>This website does not submit or store enquiry-form contents on a website server. The project form opens a pre-filled draft in your own email application. If you choose to contact me, I may receive the information you send, such as your name, email address, company or project information, links, budget range, timing and any other context you include.</p><p>Standard hosting and content-delivery infrastructure may also process technical request data such as IP address, browser or device information, requested URL and security logs in the ordinary course of delivering the website.</p></section><section class="privacy-section"><h2>Why I use information</h2><p>I use personal information only as reasonably necessary to respond to enquiries, assess a potential engagement, communicate about a project, provide agreed services, administer payments and records, protect the security of the practice and comply with legal obligations.</p></section><section class="privacy-section"><h2>Legal bases</h2><p>This practice is operated from the Russian Federation. EU or UK data-protection rules do not apply merely because someone can open the website there; they can become relevant when services are specifically offered to people in those jurisdictions. Where those rules apply, processing may rely on steps requested before a contract, performance of a contract, legal obligations, legitimate interests in professional communication and site security, or consent where the law requires it.</p></section><section class="privacy-section"><h2>Service providers and transfers</h2><p>Information may be processed by providers that are necessary to communicate with you or deliver the service, such as email, hosting or content-delivery providers and Payoneer or another agreed payment provider if an engagement proceeds to payment. These providers operate under their own terms and privacy practices.</p><p>Because clients and service providers may be located in different countries, information can be processed internationally. Where applicable law requires safeguards for an international transfer, appropriate safeguards should be used.</p></section><section class="privacy-section"><h2>Retention</h2><p>I keep personal information only for as long as it is reasonably needed for the purpose for which it was collected, to maintain necessary business and legal records, or to resolve disputes. Enquiries that do not lead to an engagement are normally reviewed for deletion within 12 months. Contract, payment and accounting records may be retained for longer where required by applicable law.</p></section><section class="privacy-section"><h2>Your choices and rights</h2><p>Depending on the law that applies to you, you may have rights to request access to, correction of, deletion of, restriction of, or a copy of your personal information, and to object to certain processing. Where processing relies on consent, you may withdraw that consent for future processing. You may also have the right to complain to the competent data-protection authority in your jurisdiction.</p><p>To make a privacy request, use the '+emailLink("Email link on this site")+'.</p></section><section class="privacy-section"><h2>Cookies, analytics and tracking</h2><p>This website does not intentionally use advertising cookies, behavioural advertising pixels or visitor analytics. It does not use website form storage, localStorage or sessionStorage for enquiry data. I do not sell personal information or use website visitor data for behavioural advertising. Because the site does not use behavioural tracking, browser “Do Not Track” signals do not change its behaviour.</p><p>Third-party infrastructure used to deliver web fonts may receive ordinary network-request information when your browser requests those resources.</p></section><section class="privacy-section"><h2>Security and automated decisions</h2><p>Reasonable technical and organisational measures are used to protect information appropriate to the nature of this independent professional practice. No automated decision-making or profiling is used to decide whether to work with a prospective client.</p></section><section class="privacy-section"><h2>Children</h2><p>This website and these professional services are not directed to children.</p></section><section class="privacy-section"><h2>Changes</h2><p>This policy may be updated when the website, service providers or data-handling practices change. The current version will be published on this page with its update date.</p></section></div></div></div></main>'+footer()}

function termsPage(){return nav()+'<main class="page-view route-fade terms-page"><div class="page-shell"><div class="page-kicker">Client information</div><h1 class="page-title">Terms &amp; Project Basics</h1><div class="page-intro"><div class="editorial-kicker">Before we work together</div><p>This page explains the general way engagements are structured. It is not an online checkout and it does not replace the written agreement for a specific project.</p></div><div class="terms-layout"><section class="terms-section"><h2>Provider</h2><p>Services are provided by Aleksandra Iagovkina, operating as a self-employed individual in the Russian Federation.</p></section><section class="terms-section"><h2>Scope, timing and fees</h2><p>Website prices are starting points. The exact service, deliverables, exclusions, timing, fee, currency and payment schedule are confirmed in writing before work begins. Work outside the agreed scope requires a separate agreement or scope update.</p></section><section class="terms-section"><h2>Payments and third-party costs</h2><p>Payment method and schedule are agreed per project. Banking, payment-provider, production, printing, development, stock, font, licensing, travel and other third-party costs are not included unless the written scope explicitly says otherwise.</p></section><section class="terms-section"><h2>Cancellations and refunds</h2><p>Cancellation and refund rules depend on the stage of work and are stated in the project agreement. Fees for work already performed, committed third-party costs and any mandatory consumer rights that apply to the client are handled according to the agreement and applicable law.</p></section><section class="terms-section"><h2>Intellectual property</h2><p>Each project agreement states what intellectual-property rights or licence the client receives and when they take effect. Unless agreed otherwise, final agreed deliverables are transferred or licensed only after full payment. Working files, methods, unused concepts, templates and pre-existing materials remain with the creator unless expressly included.</p><p>Third-party fonts, stock, software, mockups and other licensed materials remain subject to their own licence terms and cannot automatically be transferred beyond those terms.</p></section><section class="terms-section"><h2>Portfolio and confidentiality</h2><p>Portfolio use and confidentiality are agreed per project. Confidential information is not published where the parties have agreed that it must remain confidential.</p></section><section class="terms-section"><h2>No guaranteed commercial outcome</h2><p>Strategy, naming, identity and creative direction are professional services, not a guarantee of revenue, investment, market acceptance, trademark registration or other commercial result. Business, legal, financial and trademark decisions remain subject to the client’s own review and, where appropriate, specialist advice.</p></section><section class="terms-section"><h2>Privacy</h2><p>Personal information connected with enquiries and projects is handled as described in the '+routeLink("privacy","Privacy Policy")+'.</p></section><section class="terms-section"><h2>Project agreement</h2><p>For a paid engagement, the written project agreement controls if it differs from this general information. Mandatory consumer rights that cannot lawfully be excluded remain unaffected.</p></section></div></div></main>'+footer()}
function notFoundPage(){return nav()+'<main class="page-view route-fade"><div class="page-shell"><div class="page-kicker">404</div><h1 class="page-title">Page not found</h1><div class="page-intro"><div class="editorial-kicker">Wrong turn</div><p>The page you requested is not part of this site.</p></div>'+routeLink("","Return home","btn-primary")+'</div></main>'+footer()}
function caseImageMarkup(img,i,caption,variant){
  if(!img){return '<div class="case-shot"><div class="case-placeholder">Image '+String(i+1).padStart(2,"0")+'</div></div>'}
  variant=variant||"full";
  var isCadoo=img.indexOf("/cadoo/")!==-1;
  var isKitch=img.indexOf("/kitch/")!==-1;
  var isCrisp=isCadoo||img.indexOf("/lushy/")!==-1||img.indexOf("/voda-soda/")!==-1||img.indexOf("/indigo-moss/")!==-1||img.indexOf("/almonby/")!==-1||isKitch;
  var imgClass=isCrisp?"case-img case-img--cadoo":"case-img";
  if(/\.(?:avif|webp|png|jpe?g)$/i.test(img)){
    var eagerDirect=isCadoo?(i===1):i===0;
    return '<div class="case-media case-media--'+variant+'"><div class="case-shot"><img class="'+imgClass+'" src="'+img+'" width="1672" height="941" alt="'+esc(caption||"")+'" loading="'+(eagerDirect?"eager":"lazy")+'" fetchpriority="'+(eagerDirect?"high":"low")+'" decoding="async"/></div>'+(caption?'<div class="case-caption">'+esc(caption)+'</div>':'')+'</div>'
  }
  var mobile=img+"-800.webp";
  var desktop=img+"-1440.webp";
  var hq=img+"-hq.webp";
  if(isKitch){desktop=hq;}
  var eager=isCadoo?(i===1):i===0;
  var src=(variant==="pair")?mobile:(variant==="full"?hq:desktop);
  var sizes=variant==="pair"
    ? "(max-width:800px) calc(100vw - 32px), min(760px, 48vw)"
    : variant==="narrow"
      ? "(max-width:800px) calc(100vw - 32px), min(1040px, 70vw)"
      : variant==="medium"
        ? "(max-width:800px) calc(100vw - 32px), min(1220px, 82vw)"
        : "(max-width:800px) calc(100vw - 32px), min(1600px, calc(100vw - 32px))";
  var responsive;
  if(isCadoo){
    responsive=' srcset="'+img+'-720.webp 720w, '+mobile+' 800w, '+img+'-960.webp 960w, '+img+'-1200.webp 1200w, '+desktop+' 1440w, '+hq+' 1672w" sizes="'+sizes+'"';
  }else if(isKitch){
    responsive=' srcset="'+mobile+' 800w, '+hq+' 1672w" sizes="'+sizes+'"';
  }else{
    responsive=' srcset="'+mobile+' 800w, '+desktop+' 1440w, '+hq+' 1672w" sizes="'+sizes+'"';
  }
  return '<div class="case-media case-media--'+variant+'"><div class="case-shot"><img class="'+imgClass+'" src="'+src+'"'+responsive+' width="1672" height="941" alt="'+esc(caption||"")+'" loading="'+(eager?"eager":"lazy")+'" fetchpriority="'+(eager?"high":"low")+'" decoding="async"/></div>'+(caption?'<div class="case-caption">'+esc(caption)+'</div>':'')+'</div>'
}
function caseBlocks(p){
  if(!p.blocks){
    return '<div class="case-gallery">'+p.gallery.map(function(img,i){return caseImageMarkup(img,i,"","full")}).join("")+'</div>'
  }
  return '<div class="case-flow">'+p.blocks.map(function(block,blockIndex){
    var itemClass="case-flow-item case-flow-item--"+blockIndex;
    if(block.type==="text"){
      var tone=(blockIndex%3===1)?" case-text-block--accent":"";
      return '<section class="case-text-block '+itemClass+tone+'"><div class="case-text-kicker">'+esc(block.eyebrow||"")+'</div><div class="case-text-content"><h3>'+esc(block.title||"")+'</h3>'+block.body.map(function(t){return '<p>'+esc(t)+'</p>'}).join("")+'</div></section>'
    }
    if(block.type==="quote"){
      return '<section class="case-quote '+itemClass+'"><p>'+esc(block.text||"")+'</p></section>'
    }
    if(block.type==="pair"){
      var cls=block.variant||"even";
      return '<div class="case-pair case-pair--'+cls+' '+itemClass+'">'+block.images.map(function(idx,k){return caseImageMarkup(p.gallery[idx],idx,(block.captions||[])[k]||"","pair")}).join("")+'</div>'
    }
    if(block.type==="image"){
      var idx=block.images[0];
      return '<div class="'+itemClass+'">'+caseImageMarkup(p.gallery[idx],idx,block.caption||"",block.size||"full")+'</div>'
    }
    if(block.type==="feature"){
      var reverse=block.imageSide==="right";
      return '<section class="case-feature '+(reverse?"case-feature--image-right ":"")+itemClass+'"><div class="case-feature-media">'+caseImageMarkup(p.gallery[block.image],block.image,block.caption||"","medium")+'</div><div class="case-feature-copy"><div class="case-feature-kicker">'+esc(block.eyebrow||"")+'</div><h3>'+esc(block.title||"")+'</h3>'+block.body.map(function(t){return '<p>'+esc(t)+'</p>'}).join("")+'</div></section>'
    }
    if(block.type==="closing"){
      return '<section class="case-closing '+itemClass+'"><div class="case-closing-kicker">'+esc(block.eyebrow||"")+'</div><div><h3>'+esc(block.title||"")+'</h3><p>'+esc(block.body||"")+'</p></div></section>'
    }
    return ''
  }).join("")+'</div>'
}

function projectPage(p){var idx=projects.findIndex(function(x){return x.slug===p.slug});var prev=projects[(idx-1+projects.length)%projects.length];var next=projects[(idx+1)%projects.length];var desc=p.description.map(function(t){return '<p>'+esc(t)+'</p>'}).join("");return nav()+'<article class="case-page case-page--'+p.slug+' route-fade"><div class="case-top"><a href="'+routeHref("work")+'" class="case-back">← Back to work</a><div class="case-concept-label">Self-initiated venture &amp; brand concept</div><h1 class="case-title">'+esc(p.title)+'</h1><dl class="case-intro"><div class="case-fact"><dt>Project type</dt><dd>Self-initiated venture concept</dd></div><div class="case-fact"><dt>What I did</dt><dd>'+esc(p.role)+'</dd></div><div class="case-fact"><dt>Scope</dt><dd>'+esc(p.scope)+'</dd></div></dl><div class="case-description"><div class="case-description-label">Concept</div><div class="case-description-copy">'+desc+'</div></div></div>'+caseBlocks(p)+'<nav class="case-nav"><a href="'+routeHref("work/"+prev.slug)+'">Previous <span>'+esc(prev.title)+'</span></a><a href="'+routeHref("work/"+next.slug)+'">Next <span>'+esc(next.title)+'</span></a></nav></article>'+footer()}
function cleanHeadingPunctuation(){
  document.querySelectorAll("h1,h2,h3,h4,.page-title,.statement-title,.case-title").forEach(function(el){
    var w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);
    var nodes=[],n;
    while((n=w.nextNode())) nodes.push(n);
    for(var i=nodes.length-1;i>=0;i--){
      if(nodes[i].nodeValue.trim()){
        nodes[i].nodeValue=nodes[i].nodeValue.replace(/[.]\s*$/,"");
        break;
      }
    }
  });
}
function render(){
  document.body.classList.remove("menu-open");
  var h=currentRoute();
  var isCase=h.indexOf("work/")===0&&h.slice(5).indexOf("/")===-1;
  if(isCase){var slug=h.slice(5);var p=projects.find(function(x){return x.slug===slug});app.innerHTML=p?projectPage(p):workPage()}
  else if(h==="work"){app.innerHTML=workPage()}
  else if(h==="services"){app.innerHTML=servicesPage()}
  else if(h==="method"){app.innerHTML=methodPage()}
  else if(h==="about"){app.innerHTML=aboutPage()}
  else if(h==="start-a-project"){app.innerHTML=startPage()}
  else if(h==="privacy"){app.innerHTML=privacyPage()}
  else if(h==="terms"){app.innerHTML=termsPage()}
  else if(h===""){app.innerHTML=home()}
  else{app.innerHTML=notFoundPage()}
  cleanHeadingPunctuation();
  bind();
}
function closeMobileMenu(menuToggle,mobileMenu,returnFocus){
  document.body.classList.remove("menu-open");
  if(menuToggle){
    menuToggle.setAttribute("aria-expanded","false");
    menuToggle.setAttribute("aria-label","Open menu");
  }
  if(mobileMenu) mobileMenu.setAttribute("aria-hidden","true");
  if(returnFocus&&menuToggle) menuToggle.focus();
}
function bind(){
  var menuToggle=document.querySelector(".target-menu-toggle");
  var mobileMenu=document.querySelector(".mobile-menu");
  if(menuToggle&&mobileMenu){
    menuToggle.addEventListener("click",function(){
      var open=!document.body.classList.contains("menu-open");
      if(!open){closeMobileMenu(menuToggle,mobileMenu,false);return}
      document.body.classList.add("menu-open");
      menuToggle.setAttribute("aria-expanded","true");
      menuToggle.setAttribute("aria-label","Close menu");
      mobileMenu.setAttribute("aria-hidden","false");
      var first=mobileMenu.querySelector("a[href]");
      if(first) first.focus();
    });
    document.addEventListener("keydown",function(e){
      if(!document.body.classList.contains("menu-open")) return;
      if(e.key==="Escape"){
        e.preventDefault();
        closeMobileMenu(menuToggle,mobileMenu,true);
        return;
      }
      if(e.key==="Tab"){
        var focusable=Array.prototype.slice.call(mobileMenu.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])'));
        if(!focusable.length) return;
        var first=focusable[0],last=focusable[focusable.length-1];
        if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
        else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
      }
    });
  }
  document.querySelectorAll("[data-contact-email]").forEach(function(link){
    link.addEventListener("click",function(e){
      e.preventDefault();
      window.location.href="mailto:"+contactEmail();
    });
  });
  var form=document.getElementById("project-form");
  if(form){form.addEventListener("submit",function(e){e.preventDefault();var fd=new FormData(form);var body=[
    "Name: "+(fd.get("name")||""),
    "Email: "+(fd.get("email")||""),
    "Current stage: "+(fd.get("stage")||"Not sure yet"),
    "Approximate investment range: "+(fd.get("budget")||"Not sure yet"),
    "",
    "What I am trying to figure out:",
    fd.get("decision")||"",
    "",
    "What I already have to build from:",
    fd.get("assets")||"",
    "",
    "Timing / links / additional context:",
    fd.get("details")||""
  ].join("\n");window.location.href="mailto:"+contactEmail()+"?subject="+encodeURIComponent("Website inquiry from "+(fd.get("name")||"website"))+"&body="+encodeURIComponent(body)})}
}
render();
(function(){
  var doPrefetch=function(){
    ["./assets/cadoo/cadoo-01-720.webp","./assets/cadoo/cadoo-02-720.webp"].forEach(function(url){
      var l=document.createElement("link");
      l.rel="prefetch";
      l.as="image";
      l.href=url;
      document.head.appendChild(l);
    });
  };
  if("requestIdleCallback" in window){requestIdleCallback(doPrefetch,{timeout:2500})}
  else{setTimeout(doPrefetch,1800)}
})();

